class User:
    def __init__(self, name, email):
        self.name = name
        self.email = email
        self.role = "user"


_EDITABLE_FIELDS = ("name", "email")


def update_user(user, data):
    """Apply only allowlisted, user-editable fields from the request body."""
    for key in _EDITABLE_FIELDS:
        if key in data:
            setattr(user, key, data[key])
    return user

