class User:
    def __init__(self, name, email):
        self.name = name
        self.email = email
        self.role = "user"


def update_user(user, data):
    # INCOMPLETE FIX: denies 'role' but still copies every other key, so an
    # attacker can set arbitrary attributes (is_staff, password_hash, ...).
    for key, value in data.items():
        if key == "role":
            continue
        setattr(user, key, value)
    return user
